import {readAuthoring,sceneCells} from './authoring-model.js';
import {questWriteSource} from './quest-runtime.js';
import {compileScript} from './script-engine.js';
import {inBounds} from './model.js';
const BASE=0x08000000;
export function allocateScript(output,source,reason){const checked=compileScript(source,0,'frlg'),at=output.allocate(checked.bytes,reason),compiled=compileScript(source,at,'frlg');output.write(at,compiled.bytes);return at+compiled.entryOffset;}
export function areaResetSource(project,n,runtime){const flag=project.questFlags.find(q=>q.id===n.runtime.areaActiveFlag);if(!flag)throw Error('Save the scene again to reserve its area-entry state.');return [...questWriteSource(runtime,flag.slot,false,'@reset_end'),'@reset_end:','return'].join('\n');}
export function sceneBoundary(n,map){const cells=sceneCells(n,map),inside=new Set(cells.map(c=>c.x+','+c.y)),out=new Map();for(const c of cells)for(const[dx,dy]of[[0,-1],[0,1],[-1,0],[1,0]]){const p={x:c.x+dx,y:c.y+dy};if(inBounds(map,p.x,p.y)&&!inside.has(p.x+','+p.y))out.set(p.x+','+p.y,p);}return [...out.values()];}
export function installArrivalState(output,reader,project,map,native,runtime,entryScripts=[],fieldCommands=[]){const a=readAuthoring(project),flags=[];for(const n of map.markers)if(n.runtime?.areaActiveFlag&&n.runtime.enabled!==false)flags.push([n.runtime.areaActiveFlag,false]);if(a.presentation.visitFlags?.[map.id])flags.push([a.presentation.visitFlags[map.id],true]);if(!flags.length&&!entryScripts.length&&!fieldCommands.length)return false;
 const table=Number.isInteger(native.scripts)?native.scripts:reader.ptr((native.sourceAddress??native.address)+8),entries=[];if(table>=0){let at=table,ended=false;for(let i=0;i<32;i++,at+=5){if(!reader.valid(at,1))break;const type=reader.u8(at);if(!type){ended=true;break;}if(type>7||!reader.valid(at,5)||reader.ptr(at+1)<0)throw Error('The map script table is not structurally verified.');entries.push({type,pointer:reader.u32(at+1)});}if(!ended)throw Error('The map script table has no terminator.');}
 const original=entries.find(e=>e.type===3);if(entries.filter(e=>e.type===3).length>1)throw Error('Multiple native on-transition scripts need an explicit adapter.');const commands=[...fieldCommands];for(const[id,value]of flags){const q=project.questFlags.find(q=>q.id===id);if(!q)throw Error('The arrival state flag is missing.');commands.push(...questWriteSource(runtime,q.slot,value,'@arrival_done'));}commands.push('@arrival_done:',original?'goto '+original.pointer:'end');const at=allocateScript(output,commands.join('\n'),'Map arrival state');if(original)original.pointer=BASE+at;else entries.push({type:3,pointer:BASE+at});
 // New maps own their scripts and can reserve a map-local temporary variable.
 // Original maps may already use these variables through called scripts.
 if(entryScripts.length){if(!map.rom?.generated||entries.some(e=>e.type===1||e.type===2))throw Error('Map-enter scenes need a generated map with no original load/frame scripts.');const load=allocateScript(output,'setvar 0x400F 0\nend','Scene entry initialization'),run=allocateScript(output,'setvar 0x400F 1\n'+entryScripts.map(at=>'call '+(BASE+at)).join('\n')+'\nend','Scene on-frame queue'),table=new Uint8Array(10),tv=new DataView(table.buffer);tv.setUint16(0,0x400f,true);tv.setUint16(2,0,true);tv.setUint32(4,BASE+run,true);entries.push({type:1,pointer:BASE+load},{type:2,pointer:BASE+output.allocate(table,'Scene entry condition')});}
 const data=new Uint8Array(entries.length*5+1),v=new DataView(data.buffer);entries.forEach((e,i)=>{data[i*5]=e.type;v.setUint32(i*5+1,e.pointer,true);});output.int(native.address+8,BASE+output.allocate(data,'Map scripts with project arrival state'));return true;
}
